const decisions = JSON.parse(items[0].json.output);
const mainJson = $('Payload_Builder').first().json;

// Map decisions by type for safe lookup
const decisionMap = {};
decisions.forEach(d => {
  decisionMap[d.type.toLowerCase()] = d.decision;
});

// Apply classifications back onto the main json actuators
const updatedActuators = mainJson.actuators.map(a => {
  const decision = decisionMap[a.type.toLowerCase()];

  if (!decision) return a; // no decision found, leave untouched

  if (a.control_mode === 'auto') {
    return {
      ...a,
      classification: decision === 'TURN ON' ? 'TURN-ON' : 'KEEP-OFF'
    };
  }

  if (a.control_mode === 'semi-auto') {
    const status   = a.status.toLowerCase();
    const deciding = decision.toLowerCase();

    let classification;
    if      (status === 'off' && deciding === 'turn on')  classification = 'TURN-ON';
    else if (status === 'on'  && deciding === 'turn off') classification = 'TURN-OFF';
    else if (status === 'off' && deciding === 'turn off') classification = 'KEEP-OFF';
    else if (status === 'on'  && deciding === 'turn on')  classification = 'KEEP-ON';
    else classification = a.classification; // fallback

    return { ...a, classification };
  }

  return a; // fallback for unknown control mode
});

return [{ json: { ...mainJson, actuators: updatedActuators } }];

const mainJson = { ...( $('History_Loader').first().json ) };
const raw = $('Weather_Agent').first().json.output;
const weather = JSON.parse(raw);
const weatherRaw = $('Weather_API_Call').first().json;

mainJson.weather.summary = weather.summary;
mainJson.weather.state = weather.state;
mainJson.weather.precipitation_probability = weather.precipitation_probability;

// ─── Build weather insights ───────────────────────────────────────────────────
const times    = weatherRaw.hourly.time;
const temps    = weatherRaw.hourly.temperature_2m;
const humidity = weatherRaw.hourly.relative_humidity_2m;
const precip   = weatherRaw.hourly.precipitation_probability;

// Find max and min temperature
let maxTemp = { value: -Infinity, time: null };
let minTemp = { value:  Infinity, time: null };
temps.forEach((t, i) => {
  if (t > maxTemp.value) maxTemp = { value: t, time: times[i] };
  if (t < minTemp.value) minTemp = { value: t, time: times[i] };
});

// Keep only every 3 hours to reduce size (48h → 16 entries)
const hourly = times
  .map((t, i) => ({
    time:                      t,
    temperature:               temps[i],
    humidity:                  humidity[i],
    precipitation_probability: precip[i]
  }))
  .filter((_, i) => i % 3 === 0);

mainJson.weather.insights = {
  highlights: {
    max_temperature: maxTemp,
    min_temperature: minTemp
  },
  hourly
};

return [{ json: mainJson }];

