return [{ json: mainJson }];

const entities = items.map(i => i.json);
const byId = (id) => entities.find(e => e.entity_id === id);

// ─── Helpers ─────────────────────────────────────────────────────────────────

function randomRunId() {
  const hex = () => Math.floor(Math.random() * 0xffffff).toString(16).padStart(6, '0');
  return `${hex()}-${Math.floor(Math.random() * 0xffffffffffff).toString(16).padStart(12, '0')}`;
}

function toISO(datetimeStr) {
  if (!datetimeStr || datetimeStr === 'unknown') return null;
  return new Date(datetimeStr.replace(' ', 'T') + 'Z');
}

function formatTime(date) {
  if (!date) return null;
  const hh = String(date.getUTCHours()).padStart(2, '0');
  const mm = String(date.getUTCMinutes()).padStart(2, '0');
  return `${hh}:${mm}`;
}

function diffMinutes(from, to) {
  if (!from || !to) return null;
  return Math.round((to - from) / 60000);
}

// ✅ Safe parsing for real sensors
function safeParse(value) {
  if (value === null || value === undefined) return null;
  if (value === 'unknown' || value === 'unavailable') return null;

  const num = parseFloat(value);
  return isNaN(num) ? null : num;
}

const now = new Date();

// ─── Entity lookups ───────────────────────────────────────────────────────────

const zone         = byId('zone.home');
const cropType     = byId('input_text.crop_type');
const growthStage  = byId('input_text.growth_stage');
const priorityMode = byId('input_select.priority_mode');

// ✅ Real sensor entities
const soilMoisture = byId('sensor.soil_moisture');
const temperature  = byId('sensor.temperature');
const airHumidity  = byId('sensor.air_humidity');
const luminosity   = byId('sensor.luminosity');

const isAuto     = (mode) => mode && mode.toLowerCase().startsWith('auto');
const isSemiAuto = (mode) => mode && mode.toLowerCase().startsWith('semi');

// ─── Actuator builder ─────────────────────────────────────────────────────────

function buildActuator(type) {
  const controlModeRaw = byId(`input_select.${type}_control_mode`)?.state ?? null;
  const status         = byId(`input_boolean.${type}_status`)?.state ?? null;

  const executeAtDate    = toISO(byId(`input_datetime.${type}_excecute_at`)?.state);
  const executeUntilDate = toISO(byId(`input_datetime.${type}_excecute_until`)?.state);
  const reEvalStartDate  = toISO(byId(`input_datetime.${type}_re_evaluation_start`)?.state);
  const reEvalEndDate    = toISO(byId(`input_datetime.${type}_re_evaluation_end`)?.state);

  const executeAtStr    = formatTime(executeAtDate);
  const executeUntilStr = formatTime(executeUntilDate);

  const reEvalExpired  = reEvalEndDate && now > reEvalEndDate;
  const reEvalStartStr = reEvalExpired ? null : formatTime(reEvalStartDate);
  const reEvalEndStr   = reEvalExpired ? null : formatTime(reEvalEndDate);

  let controlMode;
  if (isAuto(controlModeRaw))          controlMode = 'auto';
  else if (isSemiAuto(controlModeRaw)) controlMode = 'semi-auto';
  else                                 controlMode = controlModeRaw;

  const isFutureReEval = !reEvalExpired && reEvalStartDate && now < reEvalStartDate;

  if (isFutureReEval) {
    return {
      type,
      status,
      control_mode: controlMode,
      classification: 'FUTURE-RE-EVALUATING',
      skipped: true,
      ...(isSemiAuto(controlModeRaw) ? { recommended_action: null } : {}),
      run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
      re_evaluation: {
        active: true,
        skipped: true,
        interval: { start: reEvalStartStr, end: reEvalEndStr }
      }
    };
  }

  if (isAuto(controlModeRaw)) {
    const executeUntilExpired = !executeUntilDate || now > executeUntilDate;

    if (executeUntilExpired) {
      return {
        type,
        status,
        control_mode: controlMode,
        classification: 'FREE',
        skipped: false,
        run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
        re_evaluation: { active: false, skipped: false, interval: { start: null, end: null } }
      };
    }

    const duration = diffMinutes(executeAtDate, executeUntilDate);

    if (executeAtDate && now < executeAtDate) {
      return {
        type,
        status,
        control_mode: controlMode,
        classification: 'PENDING',
        skipped: true,
        run: {
          active: true,
          execute_at: executeAtStr,
          duration_minutes: duration,
          execute_until: executeUntilStr
        },
        re_evaluation: { active: false, skipped: false, interval: { start: reEvalStartStr, end: reEvalEndStr } }
      };
    } else {
      return {
        type,
        status,
        control_mode: controlMode,
        classification: 'WORKING',
        skipped: true,
        run: {
          active: true,
          execute_at: executeAtStr,
          duration_minutes: duration,
          execute_until: executeUntilStr
        },
        re_evaluation: { active: false, skipped: false, interval: { start: reEvalStartStr, end: reEvalEndStr } }
      };
    }
  }

  if (isSemiAuto(controlModeRaw)) {
    return {
      type,
      status,
      control_mode: controlMode,
      classification: status === 'on' ? 'ON' : 'OFF',
      skipped: false,
      recommended_action: null,
      run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
      re_evaluation: { active: false, skipped: false, interval: { start: null, end: null } }
    };
  }

  return {
    type,
    status,
    control_mode: controlMode,
    classification: null,
    skipped: false,
    run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
    re_evaluation: { active: false, skipped: false, interval: { start: null, end: null } }
  };
}

// ─── Warnings ─────────────────────────────────────────────────────────────────

const warningKeys = [
  'frost_risk',
  'heavy_rainfall',
  'high_humidity_level',
  'high_temperature_detected',
  'insufficient_sunlight',
  'excessive_sunlight',
  'low_soil_moisture',
  'overwatering',
  'strong_wind'
];

const warnings = warningKeys.map(key => ({
  name: key,
  active: false,
  severity: null,
  description: null
}));

// ─── Build actuators ──────────────────────────────────────────────────────────

const pumpActuator = buildActuator('pump');
const fanActuator  = buildActuator('fan');

// ─── Assemble output ──────────────────────────────────────────────────────────

const output = {
  meta: {
    run_id: randomRunId(),
    triggered_at: now.toISOString().slice(0, 19)
  },
  location: {
    latitude:  zone?.attributes?.latitude  ?? null,
    longitude: zone?.attributes?.longitude ?? null,
    timezone:  'Africa/Algiers'
  },
  crop: {
    type:         cropType?.state     ?? null,
    growth_stage: growthStage?.state  ?? null,
    mode:         priorityMode?.state ?? null
  },
  sensors: [
    { type: 'soil_moisture', value: safeParse(soilMoisture?.state), description: null },
    { type: 'temperature',   value: safeParse(temperature?.state),  description: null },
    { type: 'air_humidity',  value: safeParse(airHumidity?.state),  description: null },
    { type: 'luminosity',    value: safeParse(luminosity?.state),   description: null }
  ],
  actuators: [pumpActuator, fanActuator],
  notifications: null,
  warnings,
  recommendation: null,
  weather: {
    precipitation_probability: null,
    state: null,
    summary: null
  },
  history: {
    runs: null,
    images: null
  },
  image_processing: {
    summary: null,
    features: {
      rain_detected: null,
      water_on_leaves: null,
      cloud_cover: null,
      lighting_level: null,
      shadows_present: null,
      plant_motion_detected: null,
      motion_intensity: null
    },
    confidence: null
  }
};

return [{ json: output }];

const input = items[0].json;

// ─── Helpers ──────────────────────────────────────────────────────────────────

function shouldIncludeActuator(actuator) {
  if (actuator.control_mode === 'auto')      return actuator.skipped === false;
  if (actuator.control_mode === 'semi-auto') return actuator.classification !== 'FUTURE-RE-EVALUATING';
  return false;
}

// ─── Filter actuators first ───────────────────────────────────────────────────

const filteredActuators = (input.actuators ?? [])
  .filter(shouldIncludeActuator)
  .map(a => ({
    type:           a.type,
    status:         a.status,
    control_mode:   a.control_mode,
    classification: a.classification
  }));

// ─── Stop if no actuators passed the filter ───────────────────────────────────

if (filteredActuators.length === 0) {
  return null;
}

// ─── Filter & reshape ─────────────────────────────────────────────────────────

const output = {
  time: input.meta?.triggered_at ?? null,
  farm: input.farm ?? null,
  sensors: (input.sensors ?? []).map(s => ({
    name:  s.name,
    value: s.value
  })),
  actuators: filteredActuators
};

return [{ json: output }];

const allItems = $input.all().map(i => i.json);

// Payload is the one that has "meta" field
const payload = allItems.find(i => i.meta !== undefined);

// Runs rows — have row_number AND triggered_at but NOT timestamp
const rows = allItems.filter(i => i.row_number !== undefined && i.triggered_at !== undefined && i.timestamp === undefined);

// Image rows — have timestamp AND summary (picture analysis rows)
const imageRows = allItems.filter(i => i.timestamp !== undefined && i.summary !== undefined);

// ----------------------------------------------------------------
// RUNS HISTORY
// ----------------------------------------------------------------
let runsHistory = null;

if (rows.length > 0) {
  const sevenDaysAgo = new Date();
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
  const last7days = rows.filter(r => new Date(r.triggered_at) >= sevenDaysAgo);

  const avg = (field) => {
    const values = last7days.map(r => {
      const sensors = typeof r.sensors === 'string' ? JSON.parse(r.sensors) : r.sensors;
      return parseFloat(sensors?.[field]);
    }).filter(v => !isNaN(v));
    if (values.length === 0) return null;
    return parseFloat((values.reduce((a, b) => a + b, 0) / values.length).toFixed(2));
  };

  const waterByDay = {};
  last7days.forEach(r => {
    const day = r.triggered_at?.slice(0, 10);
    if (!day) return;
    const actuators = typeof r.actuators === 'string' ? JSON.parse(r.actuators) : r.actuators;
    const pump = Array.isArray(actuators) ? actuators.find(a => a.type === 'pump') : null;
    const duration = parseFloat(pump?.duration_minutes) || 0;
    waterByDay[day] = (waterByDay[day] || 0) + duration;
  });

  const water7d = Object.entries(waterByDay).map(([day, minutes]) => ({
    day,
    total_pump_minutes: parseFloat(minutes.toFixed(2))
  }));

  runsHistory = {
    averages_7d: {
      soil_moisture: avg('soil_moisture'),
      temperature:   avg('temperature'),
      air_humidity:  avg('air_humidity'),
      luminosity:    avg('luminosity')
    },
    water_consumption_7d: water7d,
    last_3_runs: last7days.slice(-3).map(r => {
      const sensors   = typeof r.sensors   === 'string' ? JSON.parse(r.sensors)   : r.sensors;
      const actuators = typeof r.actuators === 'string' ? JSON.parse(r.actuators) : r.actuators;
      const pump = Array.isArray(actuators) ? actuators.find(a => a.type === 'pump') : null;
      const fan  = Array.isArray(actuators) ? actuators.find(a => a.type === 'fan')  : null;
      return {
        triggered_at:          r.triggered_at,
        soil_moisture:         sensors?.soil_moisture         ?? null,
        temperature:           sensors?.temperature           ?? null,
        air_humidity:          sensors?.air_humidity          ?? null,
        luminosity:            sensors?.luminosity            ?? null,
        pump_decision:         pump?.classification           ?? null,
        pump_duration_minutes: pump?.duration_minutes         ?? null,
        fan_decision:          fan?.classification            ?? null,
        fan_duration_minutes:  fan?.duration_minutes          ?? null
      };
    })
  };
}

// ----------------------------------------------------------------
// IMAGE HISTORY
// ----------------------------------------------------------------
let imagesHistory = null;

if (imageRows.length > 0) {
  const sevenDaysAgo = new Date();
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
  const last7daysImages = imageRows.filter(r => new Date(r.timestamp) >= sevenDaysAgo);

  const parseFeatures = (raw) => {
    if (!raw) return {};
    if (typeof raw === 'object') return raw;
    try { return JSON.parse(raw); } catch { return {}; }
  };

  const parseDecision = (raw) => {
    if (!raw) return { pump: null, fan: null };
    if (typeof raw === 'object') return raw;
    try { return JSON.parse(raw); } catch { return { pump: null, fan: null }; }
  };

  const avgNum = (field) => {
    const values = last7daysImages.map(r => parseFloat(r[field])).filter(v => !isNaN(v));
    if (values.length === 0) return null;
    return parseFloat((values.reduce((a, b) => a + b, 0) / values.length).toFixed(2));
  };

  const avgBool = (field) => {
    const values = last7daysImages.map(r => {
      const features = parseFeatures(r.features);
      return features[field];
    }).filter(v => v !== null && v !== undefined);
    if (values.length === 0) return null;
    const trueCount = values.filter(v => v === true || v === 'true').length;
    return trueCount / values.length >= 0.5;
  };

  const avgMode = (field) => {
    const values = last7daysImages.map(r => {
      const features = parseFeatures(r.features);
      return features[field];
    }).filter(v => v !== null && v !== undefined);
    if (values.length === 0) return null;
    const freq = {};
    values.forEach(v => { freq[v] = (freq[v] || 0) + 1; });
    return Object.entries(freq).sort((a, b) => b[1] - a[1])[0][0];
  };

  const decisionStats = (actuator) => {
    const decisions = last7daysImages.map(r => {
      const d = parseDecision(r.actuator_decisions);
      return d?.[actuator] ?? null;
    }).filter(v => v !== null);
    if (decisions.length === 0) return null;
    const freq = {};
    decisions.forEach(v => { freq[v] = (freq[v] || 0) + 1; });
    return Object.entries(freq).sort((a, b) => b[1] - a[1])[0][0];
  };

  const last3 = last7daysImages.slice(-3).map(r => {
    const features = parseFeatures(r.features);
    const decision = parseDecision(r.actuator_decisions);
    return {
      timestamp:             r.timestamp,
      image_summary:         r.summary ?? null,
      confidence:            parseFloat(r.confidence) || null,
      rain_detected:         features.rain_detected         ?? null,
      water_on_leaves:       features.water_on_leaves       ?? null,
      cloud_cover:           features.cloud_cover           ?? null,
      lighting_level:        features.lighting_level        ?? null,
      shadows_present:       features.shadows_present       ?? null,
      plant_motion_detected: features.plant_motion_detected ?? null,
      motion_intensity:      features.motion_intensity      ?? null,
      decision: {
        pump: decision?.pump ?? null,
        fan:  decision?.fan  ?? null
      }
    };
  });

  imagesHistory = {
    averages_7d: {
      confidence:            avgNum('confidence'),
      rain_detected:         avgBool('rain_detected'),
      water_on_leaves:       avgBool('water_on_leaves'),
      cloud_cover:           avgMode('cloud_cover'),
      lighting_level:        avgMode('lighting_level'),
      shadows_present:       avgBool('shadows_present'),
      plant_motion_detected: avgBool('plant_motion_detected'),
      motion_intensity:      avgMode('motion_intensity')
    },
    decision_stats_7d: {
      pump: decisionStats('pump'),
      fan:  decisionStats('fan')
    },
    last_3_runs: last3
  };
}

// ----------------------------------------------------------------
// BUILD FINAL HISTORY
// ----------------------------------------------------------------
payload.history = {
  runs:   runsHistory,
  images: imagesHistory
};

return [{ json: payload }];

const main = items[0].json;

// ─── Weather feedback: only entries where value is null ───────────────────────
const filteredFeedback = (main.weather?.feedback ?? []).filter(f => {
  const val = Object.values(f)[0];
  return val === null;
});

// ─── Actuators: only TURN-ON (both modes) ────────────────────────────────────
const filteredActuators = (main.actuators ?? [])
  .filter(a => a.classification === 'TURN-ON')
  .map(a => ({
    type: a.type,
    run: {
      execute_at:    a.run?.execute_at    ?? null,
      execute_until: a.run?.execute_until ?? null
    },
    re_evaluation: {
      start: a.re_evaluation?.interval?.start ?? null,
      end:   a.re_evaluation?.interval?.end   ?? null
    }
  }));

// ─── History: safe check ─────────────────────────────────────────────────────
let filteredHistory = null;
if (main.history) {
  filteredHistory = {
    runs: {
      averages_7d:          main.history.runs?.averages_7d ?? null,
      water_consumption_7d: main.history.runs?.water_consumption_7d ?? null,
      last_runs:            (main.history.runs?.last_7_days_runs ?? []).slice(0, 3)
    },
    images: {
      averages_7d: main.history.images?.averages_7d ?? null,
      last_images: (main.history.images?.last_7_days ?? []).slice(0, 3)
    }
  };
}

// ─── Assemble output ──────────────────────────────────────────────────────────
const output = {
  time: main.meta?.triggered_at ?? null,
  crop: main.crop ?? null,
  weather: {
    precipitation_probability: main.weather?.precipitation_probability ?? null,
    summary:                   main.weather?.summary ?? null,
    feedback:                  filteredFeedback
  },
  image_processing: main.image_processing ?? null,
  history:          filteredHistory, // will be null if history missing
  actuators:        filteredActuators
};

return [{ json: output }];

const main = items[0].json;

const output = {
  time: main.meta.triggered_at,
  crop: main.crop ?? null,
  sensors: (main.sensors ?? []).map(s => ({
    type:  s.type,
    value: s.value
  }))
};

return [{ json: output }];

const raw      = JSON.parse($input.first().json.output);
const mainJson = { ...$('Merge the results').first().json };

// ─── Merge actuators ──────────────────────────────────────────────────────────
const decisionMap = {};
raw.actuators.forEach(a => {
  decisionMap[a.type.toLowerCase()] = a;
});
mainJson.actuators = mainJson.actuators.map(a => {
  const decision = decisionMap[a.type.toLowerCase()];
  if (!decision) return a;
  return {
    ...a,
    classification: decision.classification,
    run: {
      ...a.run,
      active:           decision.run.active,
