// ─── 0. Get input from n8n ─────────────────────────────────────────────────────
const input = $input.first().json;

const entities = [];

// ─── Helper: convert "HH:MM" to full ISO datetime using today's date ──────────
function toFullDatetime(timeStr) {
  if (!timeStr) return null;
  if (timeStr.includes('T') || timeStr.length > 5) return timeStr;
  const now = new Date();
  const yyyy = now.getFullYear();
  const mm   = String(now.getMonth() + 1).padStart(2, '0');
  const dd   = String(now.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}T${timeStr}:00`;
}

// ─── 1. n8n_response (everything except actuators) ───────────────────────────
const { actuators, ...rest } = input;

entities.push({
  entity_id: 'sensor.n8n_response',
  state: 'ok',
  value: rest
});

// ─── 2. Loop through actuators ─────────────────────────────────────────────────
const keepClassifications = ['KEEP-ON', 'KEEP-OFF', 'ON', 'OFF'];

for (const actuator of (actuators ?? [])) {
  const type           = actuator.type;
  const classification = actuator.classification;

  // ── NEED-RE-EVALUATION ──
  if (classification === 'NEED-RE-EVALUATION') {
    entities.push({
      entity_id: `input_datetime.${type}_re_evaluation_start`,
      value: toFullDatetime(actuator.re_evaluation?.interval?.start ?? null)
    });
    entities.push({
      entity_id: `input_datetime.${type}_re_evaluation_end`,
      value: toFullDatetime(actuator.re_evaluation?.interval?.end ?? null)
    });
  }

  // ── TURN-ON ──
  else if (classification === 'TURN-ON') {
    const executeAt    = actuator.run?.execute_at ?? null;
    const executeUntil = actuator.run?.execute_until ?? null;

    entities.push({
      entity_id: `input_datetime.${type}_excecute_at`,
      value: toFullDatetime(executeAt)
    });
    entities.push({
      entity_id: `input_datetime.${type}_excecute_until`,
      value: toFullDatetime(executeUntil)
    });

    // Optional: auto mode status if you want to keep it
    if (actuator.control_mode === 'auto' && !executeAt) {
      entities.push({
        entity_id: `input_boolean.${type}_status`,
        state: 'on'
      });
    }
  }

  // ── KEEP-* → nothing ──
  else if (keepClassifications.includes(classification)) {
    // intentionally empty
  }

  // ── ANY recommended_action field ──
  if (actuator.recommended_action !== undefined) {
    entities.push({
      entity_id: `input_text.${type}_recommended_action`,
      value: actuator.recommended_action
    });
  }
}

// ─── 3. Return all entities for n8n ───────────────────────────────────────────
return entities.map(e => ({ json: e }));

